// 기본 재귀
func fibRecursive(n int) int {
    if n <= 1 {
        return n
    }
    return fibRecursive(n-1) + fibRecursive(n-2)
}

// 최적화: 메모이제이션 (Go 방식)
func fibMemoized(n int) int {
    memo := make(map[int]int)

    var fib func(int) int
    fib = func(x int) int {
        if x <= 1 {
            return x
        }
        if val, ok := memo[x]; ok {
            return val
        }
        memo[x] = fib(x-1) + fib(x-2)
        return memo[x]
    }

    return fib(n)
}

// 병렬 최적화: 고루틴 사용
func fibParallel(n int) int {
    if n <= 1 {
        return n
    }

    var wg sync.WaitGroup
    var mu sync.Mutex
    results := make(map[int]int)

    // 실제로는 이 방식은 오버헤드가 커서 추천 안 함
    // 단순히 예시용

    wg.Add(1)
    go func() {
        defer wg.Done()
        mu.Lock()
        results[0] = 0
        mu.Unlock()
    }()

    wg.Wait()
    return results[0]
}

// 실용적: 반복
func fibIterative(n int) int {
    a, b := 0, 1
    for i := 0; i < n; i++ {
        a, b = b, a+b
    }
    return a
}

func main() {
    fmt.Println("fib(10) =", fibIterative(10))  // 55
}
```

