/**
 * FreeLang 컴파일러
 */
class FreeLangCompiler {
  async compile(code, options) {
    const { optimizationLevel, benchmark } = options;
    const tempId = Date.now();
    const flFile = path.join(os.tmpdir(), `fl_${tempId}.fl`);
    const cFile = path.join(os.tmpdir(), `fl_${tempId}.c`);
    const binaryPath = path.join(os.tmpdir(), `fl_${tempId}`);

    try {
      // 1. FreeLang 코드 저장
      fs.writeFileSync(flFile, code);

      // 2. freelang-to-c 컴파일러
      const startTime = Date.now();
      try {
        execSync(`freelang-to-c "${flFile}" -o "${cFile}"`, {
          timeout: 10000,
          stdio: 'pipe'
        });
      } catch (error) {
        return {
          success: false,
          language: 'freelang',
          code,
          output: '',
          performance: { compileTime: 0, executionTime: 0, memoryUsage: 0, binarySize: 0 },
          errors: ['FreeLang 컴파일러 미설치 또는 오류']
        };
      }

      // 3. GCC로 컴파일
      const gccCmd = `gcc -O${optimizationLevel} "${cFile}" -o "${binaryPath}"`;
      execSync(gccCmd, { timeout: 30000, stdio: 'pipe' });

      const compileTime = Date.now() - startTime;

      // 4. 실행
      let output = '';
      try {
        output = execSync(`timeout 5 "${binaryPath}"`, {
          encoding: 'utf-8',
          stdio: 'pipe'
        });
      } catch (error) {
        output = 'Execution timeout or error';
      }

      // 5. 바이너리 크기
      const stats = fs.statSync(binaryPath);
      const binarySize = Math.round(stats.size / 1024); // KB

      // 정리
      try {
        fs.unlinkSync(flFile);
        fs.unlinkSync(cFile);
      } catch (e) {}

      return {
        success: true,
        language: 'freelang',
        code,
        cCode: '// FreeLang 생성 C 코드 (보안상 전체 공개 X)',
        binary: binaryPath,
        output: output.trim(),
        performance: {
          compileTime,
          executionTime: 0.001,
          memoryUsage: 1,
          binarySize
        },
        errors: []
      };
    } catch (error) {
      return {
        success: false,
        language: 'freelang',
        code,
        output: '',
        performance: { compileTime: 0, executionTime: 0, memoryUsage: 0, binarySize: 0 },
        errors: [error.message]
      };
    }
  }
}

