/**
 * POST /api/compare
 * 여러 언어의 성능을 비교
 *
 * 요청 본문:
 * {
 *   "languages": ["python", "c", "go"],
 *   "code": "def fib(n): return n if n <= 1 else fib(n-1) + fib(n-2)",
 *   "testCases": [10, 20, 30, 40]
 * }
 */
router.post('/', async (req, res) => {
  try {
    const { languages = [], code, testCases = [10, 20, 30, 40] } = req.body;

    // 유효성 검사
    if (!languages || languages.length === 0) {
      return res.status(400).json({
        success: false,
        error: 'Missing required field: languages'
      });
    }

    if (!code) {
      return res.status(400).json({
        success: false,
        error: 'Missing required field: code'
      });
    }

    if (languages.length > 10) {
      return res.status(400).json({
        success: false,
        error: 'Too many languages (max 10)'
      });
    }

    // 비교
    const result = await compilerService.compare({
      languages,
      code,
      testCases
    });

    // 응답
    res.json(result);
  } catch (error) {
    console.error('Compare error:', error);
    res.status(500).json({
      success: false,
      error: error.message
    });
  }
});

module.exports = router;

