const express = require('express');
const cors = require('cors');
require('dotenv').config();

const compileRouter = require('./routes/compile');
const compareRouter = require('./routes/compare');
const examplesRouter = require('./routes/examples');

const app = express();
const PORT = process.env.PORT || 3000;

/**
 * Middleware
 */
app.use(cors());
app.use(express.json({ limit: '50mb' }));
app.use(express.urlencoded({ limit: '50mb' }));

/**
 * Request 로깅
 */
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.path}`);
  next();
});

/**
 * 헬스 체크
 */
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    uptime: process.uptime()
  });
});

/**
 * API 라우트
 */
app.use('/api/compile', compileRouter);
app.use('/api/compare', compareRouter);
app.use('/api/examples', examplesRouter);

/**
 * Root 엔드포인트
 */
app.get('/', (req, res) => {
  res.json({
    name: 'Polyglot PoC Backend',
    version: '1.0.0',
    description: '10개 언어를 지원하는 C-Centric 컴파일러 서비스',
    endpoints: {
      health: 'GET /health',
      compile: 'POST /api/compile',
      compare: 'POST /api/compare',
      examples: 'GET /api/examples',
      example: 'GET /api/examples/:id'
    },
    supportedLanguages: [
      'python',
      'c',
      'go',
      'rust',
      'typescript',
      'java',
      'kotlin',
      'freelang',
      'wasm',
      'fv'
    ]
  });
});

/**
 * 에러 핸들러
 */
app.use((err, req, res, next) => {
  console.error('Error:', err);
  res.status(500).json({
    success: false,
    error: err.message || 'Internal server error'
  });
});

/**
 * 404 핸들러
 */
app.use((req, res) => {
  res.status(404).json({
    success: false,
    error: 'Endpoint not found',
    path: req.path
  });
});

/**
 * 서버 시작
 */
app.listen(PORT, () => {
  console.log(`
╔════════════════════════════════════════╗
║  🚀 Polyglot PoC Backend Started      ║
╠════════════════════════════════════════╣
║ Server: http://localhost:${PORT}             ║
║ Health: http://localhost:${PORT}/health    ║
║ API:    http://localhost:${PORT}/api/*     ║
╚════════════════════════════════════════╝
  `);
});

module.exports = app;

