import React, { useState, useEffect } from 'react';

/**
 * 간단한 코드 에디터 (Monaco Editor 대신 textarea 사용)
 * 실제 구현에서는 @monaco-editor/react 사용 권장
 */
export default function CodeEditor({
  code,
  language,
  onChange,
  onCompile,
  isCompiling
}) {
  const [lineCount, setLineCount] = useState(1);

  useEffect(() => {
    const count = code.split('\n').length;
    setLineCount(count);
  }, [code]);

  const syntaxHighlight = (text, lang) => {
    // 간단한 문법 강조 (실제 구현에서는 Prism.js 등 사용)
    return text;
  };

  return (
    <div className="code-editor flex flex-col h-full">
      <div className="flex justify-between items-center mb-4 p-4 bg-gray-100 rounded">
        <div>
          <h3 className="text-lg font-bold text-gray-800">
            {language.toUpperCase()} Code
          </h3>
          <p className="text-sm text-gray-600">{lineCount} lines</p>
        </div>
        <button
          onClick={onCompile}
          disabled={isCompiling}
          className={`
            px-6 py-2 rounded-lg font-bold text-white transition-all
            ${isCompiling
              ? 'bg-gray-400 cursor-not-allowed'
              : 'bg-blue-600 hover:bg-blue-700 active:scale-95'
            }
          `}
        >
          {isCompiling ? '⏳ Compiling...' : '▶️ Compile & Run'}
        </button>
      </div>

      <textarea
        value={code}
        onChange={(e) => onChange(e.target.value)}
        className="
          flex-1 p-4 font-mono text-sm bg-gray-900 text-gray-100
          border-l-4 border-blue-600 focus:outline-none focus:ring-2
          focus:ring-blue-400 rounded overflow-auto
        "
        placeholder="Enter your code here..."
        spellCheck="false"
      />
    </div>
  );
}

