import React from 'react';

/**
 * 성능 비교 차트 (간단한 바 차트)
 */
export default function ComparisonChart({ results }) {
  if (!results || results.length === 0) {
    return (
      <div className="comparison-chart p-4 bg-gray-100 rounded text-center text-gray-500">
        No comparison data
      </div>
    );
  }

  // 가장 느린 시간을 기준으로 스케일 계산
  const maxTime = Math.max(
    ...results.flatMap(r => r.executionTime || [])
  );

  return (
    <div className="comparison-chart p-4 bg-white rounded border">
      <h3 className="font-bold text-lg mb-4 text-gray-800">📊 Performance Comparison</h3>

      <div className="space-y-4">
        {results.map((result, idx) => (
          <div key={idx} className="flex items-center gap-4">
            <div className="w-24 text-sm font-medium text-gray-700">
              {result.language.toUpperCase()}
            </div>

            {/* 바 차트 */}
            <div className="flex-1 bg-gray-200 rounded-full h-8 overflow-hidden relative">
              <div
                className="h-full bg-blue-600 transition-all duration-300 flex items-center justify-end pr-2"
                style={{
                  width: `${(result.executionTime[0] / maxTime) * 100}%`
                }}
              >
                <span className="text-white text-xs font-bold">
                  {result.executionTime[0].toFixed(3)}ms
                </span>
              </div>
            </div>

            {/* 메모리 */}
            <div className="w-20 text-right text-sm text-gray-600">
              {result.memoryUsage}MB
            </div>
          </div>
        ))}
      </div>

      {/* 범례 */}
      <div className="mt-4 pt-4 border-t text-xs text-gray-500 space-y-1">
        <p>• 가로 길이 = 실행 시간 (ms)</p>
        <p>• 오른쪽 숫자 = 측정 시간</p>
        <p>• 오른쪽 텍스트 = 메모리 사용량</p>
      </div>
    </div>
  );
}

