import { useState, useCallback } from 'react';
import axios from 'axios';

const API_BASE_URL = process.env.REACT_APP_API_URL || 'http://localhost:3000';

/**
 * 컴파일러 API를 위한 커스텀 훅
 */
export function useCompiler() {
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState(null);
  const [error, setError] = useState(null);

  const compile = useCallback(async (language, code, optimizationLevel = 2) => {
    setLoading(true);
    setError(null);

    try {
      const response = await axios.post(`${API_BASE_URL}/api/compile`, {
        language,
        code,
        optimizationLevel,
        benchmark: true
      });

      setResult(response.data);
      return response.data;
    } catch (err) {
      const errorMsg = err.response?.data?.error || err.message;
      setError(errorMsg);
      setResult({
        success: false,
        errors: [errorMsg]
      });
    } finally {
      setLoading(false);
    }
  }, []);

  const compare = useCallback(async (languages, code, testCases = [10, 20, 30, 40]) => {
    setLoading(true);
    setError(null);

    try {
      const response = await axios.post(`${API_BASE_URL}/api/compare`, {
        languages,
        code,
        testCases
      });

      setResult(response.data);
      return response.data;
    } catch (err) {
      const errorMsg = err.response?.data?.error || err.message;
      setError(errorMsg);
      setResult({
        success: false,
        error: errorMsg
      });
    } finally {
      setLoading(false);
    }
  }, []);

  const fetchExamples = useCallback(async () => {
    try {
      const response = await axios.get(`${API_BASE_URL}/api/examples`);
      return response.data.examples;
    } catch (err) {
      console.error('Failed to fetch examples:', err);
      return [];
    }
  }, []);

  return {
    loading,
    result,
    error,
    compile,
    compare,
    fetchExamples
  };
}

