import React, { useState, useEffect } from 'react';
import LanguageSelector from '../components/LanguageSelector';
import CodeEditor from '../components/CodeEditor';
import OutputPanel from '../components/OutputPanel';
import { useCompiler } from '../hooks/useCompiler';

/**
 * 메인 에디터 페이지
 */
export default function Editor() {
  const [language, setLanguage] = useState('python');
  const [code, setCode] = useState('print("Hello, World!")');
  const [examples, setExamples] = useState([]);
  const [optimization, setOptimization] = useState(2);

  const { loading, result, compile, fetchExamples } = useCompiler();

  // 예제 로드
  useEffect(() => {
    (async () => {
      const exs = await fetchExamples();
      setExamples(exs);
    })();
  }, [fetchExamples]);

  // 언어 변경 시 예제 업데이트
  const handleLanguageChange = (newLanguage) => {
    setLanguage(newLanguage);

    // 해당 언어의 예제 찾기
    const example = examples.find(e => e.id === 'hello-world');
    if (example && example.code[newLanguage]) {
      setCode(example.code[newLanguage]);
    }
  };

  const handleCompile = async () => {
    await compile(language, code, optimization);
  };

  const handleLoadExample = (exampleId) => {
    const example = examples.find(e => e.id === exampleId);
    if (example && example.code[language]) {
      setCode(example.code[language]);
    }
  };

  return (
    <div className="editor-page min-h-screen bg-gray-50 p-6">
      <div className="max-w-7xl mx-auto">
        {/* 헤더 */}
        <div className="mb-6">
          <h1 className="text-4xl font-bold text-gray-900 mb-2">
            🌍 Polyglot Code Compiler
          </h1>
          <p className="text-gray-600">
            Write code in 10 languages and see how they compile to C
          </p>
        </div>

        {/* 언어 선택 */}
        <div className="mb-6 bg-white rounded-lg shadow p-4">
          <h2 className="font-bold text-gray-800 mb-3">Select Language</h2>
          <LanguageSelector
            selectedLanguage={language}
            onSelect={handleLanguageChange}
          />
        </div>

        {/* 예제 선택 */}
        <div className="mb-6 bg-white rounded-lg shadow p-4">
          <h2 className="font-bold text-gray-800 mb-3">Example Code</h2>
          <div className="flex flex-wrap gap-2">
            {examples.map(example => (
              <button
                key={example.id}
                onClick={() => handleLoadExample(example.id)}
                className="px-4 py-2 bg-green-600 text-white rounded hover:bg-green-700 transition-colors text-sm font-medium"
              >
                {example.name}
              </button>
            ))}
          </div>
        </div>

        {/* 최적화 레벨 선택 */}
        <div className="mb-6 bg-white rounded-lg shadow p-4">
          <label className="block font-bold text-gray-800 mb-2">
            Optimization Level: O{optimization}
          </label>
          <input
            type="range"
            min="0"
            max="3"
            value={optimization}
            onChange={(e) => setOptimization(Number(e.target.value))}
            className="w-full"
          />
          <p className="text-sm text-gray-600 mt-2">
            O0 = No optimization | O3 = Maximum optimization
          </p>
        </div>

        {/* 메인 콘텐츠: 에디터와 결과 */}
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 mb-6">
          {/* 코드 에디터 */}
          <div className="bg-white rounded-lg shadow overflow-hidden">
            <CodeEditor
              code={code}
              language={language}
              onChange={setCode}
              onCompile={handleCompile}
              isCompiling={loading}
            />
          </div>

          {/* 결과 패널 */}
          <div className="bg-white rounded-lg shadow p-4">
            <OutputPanel result={result} loading={loading} />
          </div>
        </div>

        {/* 푸터 */}
        <div className="bg-blue-50 rounded-lg shadow p-4 border-l-4 border-blue-600">
          <h3 className="font-bold text-blue-900 mb-2">💡 How it works</h3>
          <ul className="text-sm text-blue-800 space-y-1">
            <li>✅ Python code is converted to C via Cython</li>
            <li>✅ All languages compile to native binary with gcc</li>
            <li>✅ Performance metrics measured in milliseconds</li>
            <li>✅ Compare your code across all languages in real-time</li>
          </ul>
        </div>
      </div>
    </div>
  );
}

