import React, { useState } from 'react';
import LanguageSelector from '../components/LanguageSelector';
import CodeEditor from '../components/CodeEditor';
import ComparisonChart from '../components/ComparisonChart';
import { useCompiler } from '../hooks/useCompiler';

/**
 * 언어 성능 비교 페이지
 */
export default function Comparison() {
  const [selectedLanguages, setSelectedLanguages] = useState(['python', 'c', 'go']);
  const [code, setCode] = useState('def fib(n):\n    return n if n <= 1 else fib(n-1) + fib(n-2)\n\nprint(fib(10))');
  const [comparisonResult, setComparisonResult] = useState(null);

  const { loading, compare } = useCompiler();

  const handleLanguageToggle = (language) => {
    if (selectedLanguages.includes(language)) {
      setSelectedLanguages(selectedLanguages.filter(l => l !== language));
    } else {
      if (selectedLanguages.length < 5) {
        setSelectedLanguages([...selectedLanguages, language]);
      } else {
        alert('Maximum 5 languages for comparison');
      }
    }
  };

  const handleCompare = async () => {
    if (selectedLanguages.length === 0) {
      alert('Select at least one language');
      return;
    }

    const result = await compare(selectedLanguages, code);
    setComparisonResult(result);
  };

  return (
    <div className="comparison-page min-h-screen bg-gray-50 p-6">
      <div className="max-w-7xl mx-auto">
        {/* 헤더 */}
        <div className="mb-6">
          <h1 className="text-4xl font-bold text-gray-900 mb-2">
            ⚡ Language Performance Comparison
          </h1>
          <p className="text-gray-600">
            Compare execution time, memory usage, and binary size across languages
          </p>
        </div>

        {/* 언어 선택 */}
        <div className="bg-white rounded-lg shadow p-6 mb-6">
          <h2 className="font-bold text-lg text-gray-800 mb-4">
            Select Languages ({selectedLanguages.length}/5)
          </h2>
          <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-5 gap-3">
            {[
              { id: 'python', name: 'Python', icon: '🐍' },
              { id: 'c', name: 'C', icon: '⚙️' },
              { id: 'go', name: 'Go', icon: '🐹' },
              { id: 'rust', name: 'Rust', icon: '🦀' },
              { id: 'typescript', name: 'TypeScript', icon: '📘' }
            ].map(lang => (
              <label key={lang.id} className="flex items-center gap-2 p-3 border-2 rounded cursor-pointer hover:bg-gray-50">
                <input
                  type="checkbox"
                  checked={selectedLanguages.includes(lang.id)}
                  onChange={() => handleLanguageToggle(lang.id)}
                  className="w-4 h-4"
                />
                <span className="text-lg">{lang.icon}</span>
                <span className="font-medium text-gray-800">{lang.name}</span>
              </label>
            ))}
          </div>
        </div>

        {/* 코드 입력 */}
        <div className="bg-white rounded-lg shadow p-6 mb-6">
          <h2 className="font-bold text-lg text-gray-800 mb-4">Code to Compare</h2>
          <textarea
            value={code}
            onChange={(e) => setCode(e.target.value)}
            className="
              w-full h-48 p-4 font-mono text-sm bg-gray-900 text-gray-100
              border-2 border-gray-300 focus:border-blue-600 focus:outline-none
              rounded overflow-auto
            "
            placeholder="Enter code (syntax varies by language)"
          />
        </div>

        {/* 비교 버튼 */}
        <div className="mb-6 flex gap-3">
          <button
            onClick={handleCompare}
            disabled={loading || selectedLanguages.length === 0}
            className={`
              px-8 py-3 rounded-lg font-bold text-white transition-all
              ${loading || selectedLanguages.length === 0
                ? 'bg-gray-400 cursor-not-allowed'
                : 'bg-blue-600 hover:bg-blue-700 active:scale-95'
              }
            `}
          >
            {loading ? '⏳ Comparing...' : '📊 Compare Performance'}
          </button>
        </div>

        {/* 결과 */}
        {comparisonResult && (
          <div className="space-y-6">
            <div className="bg-white rounded-lg shadow p-6">
              <ComparisonChart results={comparisonResult.results} />
            </div>

            {/* 상세 테이블 */}
            <div className="bg-white rounded-lg shadow p-6">
              <h3 className="font-bold text-lg text-gray-800 mb-4">Detailed Results</h3>
              <div className="overflow-x-auto">
                <table className="w-full text-sm">
                  <thead className="bg-gray-100 border-b-2 border-gray-300">
                    <tr>
                      <th className="px-4 py-2 text-left font-bold text-gray-700">Language</th>
                      <th className="px-4 py-2 text-right font-bold text-gray-700">Exec Time (ms)</th>
                      <th className="px-4 py-2 text-right font-bold text-gray-700">Memory (MB)</th>
                      <th className="px-4 py-2 text-right font-bold text-gray-700">Binary (KB)</th>
                      <th className="px-4 py-2 text-right font-bold text-gray-700">Compile (ms)</th>
                    </tr>
                  </thead>
                  <tbody>
                    {comparisonResult.results && comparisonResult.results.map((result, idx) => (
                      <tr key={idx} className="border-b hover:bg-gray-50">
                        <td className="px-4 py-2 font-medium text-gray-900">
                          {result.language.toUpperCase()}
                        </td>
                        <td className="px-4 py-2 text-right text-gray-700">
                          {result.executionTime && result.executionTime[0]?.toFixed(4)}
                        </td>
                        <td className="px-4 py-2 text-right text-gray-700">
                          {result.memoryUsage}
                        </td>
                        <td className="px-4 py-2 text-right text-gray-700">
                          {result.binarySize}
                        </td>
                        <td className="px-4 py-2 text-right text-gray-700">
                          {result.compileTime}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        )}

        {/* 정보 */}
        {!comparisonResult && (
          <div className="bg-blue-50 rounded-lg shadow p-6 border-l-4 border-blue-600">
            <h3 className="font-bold text-blue-900 mb-2">💡 Tips</h3>
            <ul className="text-sm text-blue-800 space-y-1">
              <li>✅ Select 2-5 languages for optimal comparison</li>
              <li>✅ Code syntax must be valid for each selected language</li>
              <li>✅ Results show execution time, memory, and binary size</li>
              <li>✅ Lower execution time and memory = better performance</li>
            </ul>
          </div>
        )}
      </div>
    </div>
  );
}

