input, textarea, select {
  font-family: inherit;
  border: 1px solid #ddd;
  padding: 8px 12px;
  border-radius: 4px;
  transition: all 0.2s;
}

input:focus, textarea:focus, select:focus {
  border-color: #3b82f6;
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.1);
  outline: none;
}

